package com.example.ancapp

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.BackHandler
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.text.KeyboardOptions
import androidx.compose.foundation.verticalScroll
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.automirrored.filled.ArrowBack
import androidx.compose.material.icons.filled.Add
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.runtime.saveable.rememberSaveable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.input.KeyboardType
import androidx.compose.ui.unit.dp
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.time.LocalDate
import java.time.format.DateTimeFormatter
import java.time.format.DateTimeParseException

private val DATE_FMT = DateTimeFormatter.ofPattern("d MMM yyyy")

class MainActivity : ComponentActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    enableEdgeToEdge()
    val db = Db(applicationContext)
    setContent { MaterialTheme { App(db) } }
  }
}

@Composable
fun App(db: Db) {
  var patients by remember { mutableStateOf<List<Patient>?>(null) }
  LaunchedEffect(Unit) { patients = withContext(Dispatchers.IO) { db.patients() } }
  var patientId by rememberSaveable { mutableLongStateOf(-1L) }
  var recording by rememberSaveable { mutableStateOf(false) }
  val patient = patients?.find { it.id == patientId }

  when {
    patient == null -> RegisterScreen(patients) { patientId = it.id }
    recording -> {
      BackHandler { recording = false }
      VisitForm(patient, db, onDone = { recording = false })
    }
    else -> {
      BackHandler { patientId = -1 }
      DetailScreen(patient, db, onBack = { patientId = -1 }, onRecord = { recording = true })
    }
  }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RegisterScreen(patients: List<Patient>?, onOpen: (Patient) -> Unit) {
  val today = LocalDate.now()
  Scaffold(topBar = { TopAppBar(title = { Text("ANC Register") }) }) { pad ->
    if (patients == null) {
      Box(Modifier.padding(pad).fillMaxSize(), Alignment.Center) { CircularProgressIndicator() }
      return@Scaffold
    }
    LazyColumn(Modifier.padding(pad), contentPadding = PaddingValues(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
      items(patients, key = { it.id }) { p ->
        Card(Modifier.fillMaxWidth().clickable { onOpen(p) }) {
          Column(Modifier.padding(16.dp)) {
            Text(p.name, style = MaterialTheme.typography.titleMedium)
            Text("Age ${ageYears(p.dob, today)} · ${gaWeeks(p.edd, today)} weeks pregnant")
            Text("Due ${p.edd.format(DATE_FMT)}", style = MaterialTheme.typography.bodyMedium)
          }
        }
      }
    }
  }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun DetailScreen(patient: Patient, db: Db, onBack: () -> Unit, onRecord: () -> Unit) {
  val today = LocalDate.now()
  var visits by remember { mutableStateOf<List<Visit>?>(null) }
  LaunchedEffect(patient.id) { visits = withContext(Dispatchers.IO) { db.visits(patient.id) } }
  Scaffold(
    topBar = {
      TopAppBar(
        title = { Text(patient.name) },
        navigationIcon = { IconButton(onClick = onBack) { Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back") } },
      )
    },
    floatingActionButton = {
      ExtendedFloatingActionButton(onClick = onRecord, icon = { Icon(Icons.Default.Add, null) }, text = { Text("Record visit") })
    },
  ) { pad ->
    LazyColumn(Modifier.padding(pad), contentPadding = PaddingValues(12.dp, 12.dp, 12.dp, 88.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
      item {
        Text(
          "Age ${ageYears(patient.dob, today)} · ${gaWeeks(patient.edd, today)} weeks · Due ${patient.edd.format(DATE_FMT)}",
          style = MaterialTheme.typography.bodyLarge,
        )
        Text("ANC visits", style = MaterialTheme.typography.titleMedium, modifier = Modifier.padding(top = 12.dp))
      }
      val v = visits
      if (v != null && v.isEmpty()) item { Text("No visits recorded.") }
      items(v.orEmpty()) { visit ->
        Card(Modifier.fillMaxWidth()) {
          Column(Modifier.padding(16.dp)) {
            Text(
              visit.date.format(DATE_FMT) + (visit.gaWeeks?.let { " · $it wks" } ?: ""),
              style = MaterialTheme.typography.titleSmall,
            )
            Text("Weight ${visit.weightKg} kg · BP ${visit.systolic}/${visit.diastolic} mmHg")
            Text("Hb " + (visit.hbGdl?.let { "$it g/dL" } ?: "not recorded"))
            if (visit.dangerSigns.isNotEmpty()) {
              Text("Danger signs: ${visit.dangerSigns.joinToString()}", color = MaterialTheme.colorScheme.error)
            }
            if (visit.notes.isNotBlank()) Text(visit.notes, style = MaterialTheme.typography.bodySmall)
          }
        }
      }
    }
  }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun VisitForm(patient: Patient, db: Db, onDone: () -> Unit) {
  val today = LocalDate.now()
  var date by rememberSaveable { mutableStateOf(today.toString()) }
  var ga by rememberSaveable { mutableStateOf(gaWeeks(patient.edd, today).toString()) }
  var weight by rememberSaveable { mutableStateOf("") }
  var sys by rememberSaveable { mutableStateOf("") }
  var dia by rememberSaveable { mutableStateOf("") }
  var signs by rememberSaveable { mutableStateOf(listOf<String>()) }
  var notes by rememberSaveable { mutableStateOf("") }
  var error by remember { mutableStateOf<String?>(null) }
  var saving by remember { mutableStateOf(false) }
  val scope = rememberCoroutineScope()

  fun save() {
    val d = try { LocalDate.parse(date.trim()) } catch (_: DateTimeParseException) { null }
    val g = ga.trim().toIntOrNull()
    val w = weight.trim().replace(',', '.').toDoubleOrNull()
    val s = sys.trim().toIntOrNull()
    val di = dia.trim().toIntOrNull()
    error = when {
      d == null -> "Visit date must be YYYY-MM-DD"
      d.isAfter(today) -> "Visit date cannot be in the future"
      g == null || g !in 1..45 -> "Gestational age must be 1–45 weeks"
      w == null || w !in 20.0..250.0 -> "Weight must be 20–250 kg"
      s == null || s !in 50..300 -> "Systolic must be 50–300 mmHg"
      di == null || di !in 20..200 -> "Diastolic must be 20–200 mmHg"
      di >= s -> "Diastolic must be lower than systolic"
      else -> null
    }
    if (error != null) return
    saving = true
    scope.launch {
      withContext(Dispatchers.IO) { db.addVisit(patient.id, Visit(d!!, g, w!!, s!!, di!!, null, signs, notes.trim())) }
      onDone()
    }
  }

  Scaffold(
    topBar = {
      TopAppBar(
        title = { Text("New visit · ${patient.name}") },
        navigationIcon = { IconButton(onClick = onDone) { Icon(Icons.AutoMirrored.Filled.ArrowBack, "Cancel") } },
      )
    },
  ) { pad ->
    Column(
      Modifier.padding(pad).imePadding().verticalScroll(rememberScrollState()).padding(16.dp),
      verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
      val num = KeyboardOptions(keyboardType = KeyboardType.Number)
      OutlinedTextField(date, { date = it }, Modifier.fillMaxWidth(), label = { Text("Visit date (YYYY-MM-DD)") }, singleLine = true)
      OutlinedTextField(ga, { ga = it }, Modifier.fillMaxWidth(), label = { Text("Gestational age (weeks)") }, singleLine = true, keyboardOptions = num)
      OutlinedTextField(weight, { weight = it }, Modifier.fillMaxWidth(), label = { Text("Weight (kg)") }, singleLine = true,
        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal))
      Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
        OutlinedTextField(sys, { sys = it }, Modifier.weight(1f), label = { Text("Systolic (mmHg)") }, singleLine = true, keyboardOptions = num)
        OutlinedTextField(dia, { dia = it }, Modifier.weight(1f), label = { Text("Diastolic (mmHg)") }, singleLine = true, keyboardOptions = num)
      }
      Text("Danger signs", style = MaterialTheme.typography.titleSmall, modifier = Modifier.padding(top = 8.dp))
      CheckRow("None", signs.isEmpty()) { signs = emptyList() }
      DANGER_SIGNS.forEach { sign ->
        CheckRow(sign, sign in signs) { checked ->
          signs = if (checked) DANGER_SIGNS.filter { it in signs || it == sign } else signs - sign
        }
      }
      OutlinedTextField(notes, { notes = it }, Modifier.fillMaxWidth(), label = { Text("Notes") }, minLines = 3)
      error?.let { Text(it, color = MaterialTheme.colorScheme.error) }
      Button(::save, Modifier.fillMaxWidth(), enabled = !saving) { Text("Save visit") }
    }
  }
